//! Run via `npm run api:generate` / `npm run api:check` in frontend/.

use std::path::Path;

use lobotomy_core::view::{Event, Found, Match, MatchKind};
use lobotomyd::gui::protocol::Push;
use serde_json::json;

fn main() -> anyhow::Result<()> {
    let declarations = lobotomyd::gui::bindings::declarations();
    let declarations = declarations.lines().map(str::trim_end).collect::<Vec<_>>().join("\n");
    let output = format!(
        "// Generated by npm run api:generate. Do not edit.\n\
         // JSON integers are JS numbers and may lose precision above Number.MAX_SAFE_INTEGER.\n\n{}\n",
        declarations.trim_end()
    );
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../frontend/src/api/generated.ts");
    if std::env::args().any(|arg| arg == "--check") {
        anyhow::ensure!(
            std::fs::read_to_string(&path).ok().as_deref() == Some(&output),
            "GUI types are stale; run npm run api:generate in frontend/"
        );
    } else {
        std::fs::write(path, output)?;
    }

    // Serialize the actual wire types. The frontend script checks these literals against the
    // generated types: enum tags/renames, required nullable fields, arbitrary JSON and numbers.
    let search = Found {
        matches: vec![
            Match { kind: MatchKind::Item, id: "item".into(), seq: Some(1) },
            Match { kind: MatchKind::Message, id: "queued".into(), seq: None },
        ],
        more: false,
    };
    let events: Vec<_> = [json!({ "task_id": "task" }), json!(null), json!([1, "text"]), json!(true)]
        .into_iter()
        .enumerate()
        .map(|(index, payload)| Event {
            seq: if index == 0 { i64::MAX } else { index as i64 },
            kind: "future.changed".into(),
            entity: "task".into(),
            payload,
            command_id: (index == 0).then(|| "command".into()),
            caller: (index == 0).then(|| "user".into()),
            caller_turn_id: None,
        })
        .collect();
    // Real read models from a small in-memory database include serde flatten and skipped fields.
    use lobotomy_core::{Caller, Db};
    let db = Db::open_in_memory()?;
    db.execute(
        &Caller::User,
        &lobotomy_core::project::Onboard {
            request_id: "onboard".into(),
            project_id: "project".into(),
            repo_path: "/repo".into(),
            branch: "main".into(),
            head: "base".into(),
            author_name: "User".into(),
            author_email: "user@example.com".into(),
        },
    )?;
    let task = db.execute(
        &Caller::User,
        &lobotomy_core::task::CreateTask {
            request_id: "create".into(),
            title: "Task".into(),
            body: "Body".into(),
            criteria: "Works".into(),
            executor: "Malkuth".into(),
        },
    )?;
    db.execute(&Caller::Runtime, &lobotomy_core::task::StartAttempt { task_id: task.id.clone(), code_start: None })?;
    let workspace = db.read(|c| lobotomy_core::workspace::current_workspace(c, "worker"))?.unwrap();
    db.execute(
        &Caller::Runtime,
        &lobotomy_core::workspace::WorkspaceReady {
            workspace_id: workspace.id,
            target: workspace.target,
            head: workspace.head,
        },
    )?;
    db.execute(&Caller::Runtime, &lobotomy_core::turn::RegisterTurn { role: "Malkuth".into() })?;
    let models = lobotomyd::gui::bindings::fixtures(&db)?;
    let message = lobotomy_core::task::SendMessage {
        request_id: "send".into(),
        role: "Malkuth".into(),
        task_id: None,
        body: "text".into(),
        reply_to: None,
    };
    println!(
        "{}",
        json!({
            "search": search,
            "models": models,
            "task": db.read(|c| lobotomy_core::view::task_detail(c, &task.id))?,
            "message": message,
            "pushes": [
                Push::Events { project: "project", events: &events },
                Push::Thread { project: "angela", role: "Angela", seq: 1 },
                Push::Host, Push::Tick, Push::Resync,
                Push::Live { project: "project", live: &std::collections::HashMap::new() },
            ],
        })
    );
    Ok(())
}
